/* non.js — 古北欧语（Old Norse, ᚢᛁᛚᛏ ᛘᛅᛚ）界面文案翻译表。缺失 key 会回退到 zh-CN。
 *
 * 书写体系：古北欧语（约 800–1100 年，维京时代），以卢恩字母书写，采用
 * Younger Futhark（ᚠᚢᚦᚬᚱᚴ，16 字母系统）。转写用标准古北欧语正字法，
 * 保留 ǫ、þ、ð、á、é、í、ó、ú、ý、æ、ø 等音标（如 geyma、nafn、konungr、
 * heimr、skip、hús、orð、gera、sjá、mikill、lítill、góðr、illr、skrifa）。
 * 凡当代技术名词在古北欧无从考据者，以「音译 + 中文回退」处理，确保每个 key 有值。
 *
 * 值格式统一为「本语言书写 (中文原文/拉丁转写)」，例如：
 *     save: 'ᚷᛁᛅᛘ (保存/geyma)'
 * 斜杠前为中文原文（源语言 zh-CN 的原样文案），斜杠后为古北欧语拉丁转写；
 * {花括号} 之间的插入占位符一律原样保留，一个字符都不改。
 *
 * 面板「界面设置」中可开关括号注释，并可只显示中文或只显示转写
 * （见 store/settings 的 bracketEnabled / bracketLang）。
 *
 * 注意：disclaimerText 为具法律效力的中文原文，为免机械翻译带来法律风险，
 * 逐字保留 zh-CN 原样，不翻译、不改写。 */
